import sys
def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); q = int(data[1])
    row1 = data[2]; row2 = data[3]
    # A state describes the four boundary cells of a block of columns:
    # (left top, left bottom, right top, right bottom); -1 = sealed, else a region label.
    def canon(t):
        mp = {}
        out = []
        for v in t:
            if v < 0:
                out.append(-1)
            else:
                if v not in mp:
                    mp[v] = len(mp)
                out.append(mp[v])
        return tuple(out)
    def merge(a, b):
        parent = list(range(8))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        joins = 0
        for x, y in ((a[2], b[0]), (a[3], b[1])):
            if x >= 0 and y >= 0:
                rx = find(x); ry = find(y + 4)
                if rx != ry:
                    parent[rx] = ry
                    joins += 1
        res = []
        for v, off in ((a[0], 0), (a[1], 0), (b[2], 4), (b[3], 4)):
            res.append(-1 if v < 0 else find(v + off))
        return canon(res), joins
    leaves = {
        (True, True): ((0, 0, 0, 0), 1),
        (True, False): ((0, -1, 0, -1), 1),
        (False, True): ((-1, 0, -1, 0), 1),
        (False, False): ((-1, -1, -1, -1), 0),
    }
    states = [s for s, _ in leaves.values()]
    index = {s: i for i, s in enumerate(states)}
    table = {}
    i = 0
    while i < len(states):
        a = states[i]
        for b in list(states):
            for x, y in ((a, b), (b, a)):
                if (x, y) in table:
                    continue
                c, joins = merge(x, y)
                if c not in index:
                    index[c] = len(states); states.append(c)
                table[(x, y)] = (index[c], joins)
        i += 1
    S = len(states)
    T = [0] * (S * S)
    for (x, y), (ci, joins) in table.items():
        T[index[x] * S + index[y]] = ci * 4 + joins
    leaf_idx = {k: (index[s], c) for k, (s, c) in leaves.items()}
    sealed = index[(-1, -1, -1, -1)]
    size = 1
    while size < n:
        size *= 2
    st = [sealed] * (2 * size)
    cnt = [0] * (2 * size)
    open1 = [ch == 46 for ch in row1]
    open2 = [ch == 46 for ch in row2]
    for c in range(n):
        si, cc = leaf_idx[(open1[c], open2[c])]
        st[size + c] = si; cnt[size + c] = cc
    for i in range(size - 1, 0, -1):
        v = T[st[2 * i] * S + st[2 * i + 1]]
        st[i] = v >> 2; cnt[i] = cnt[2 * i] + cnt[2 * i + 1] - (v & 3)
    out = []
    p = 4
    for _ in range(q):
        kind = data[p]; a = int(data[p + 1]); b = int(data[p + 2]); p += 3
        if kind == b'1':
            c = b - 1
            if a == 1:
                open1[c] = not open1[c]
            else:
                open2[c] = not open2[c]
            i = size + c
            st[i], cnt[i] = leaf_idx[(open1[c], open2[c])]
            i >>= 1
            while i:
                v = T[st[2 * i] * S + st[2 * i + 1]]
                st[i] = v >> 2; cnt[i] = cnt[2 * i] + cnt[2 * i + 1] - (v & 3)
                i >>= 1
        else:
            l = a - 1 + size; r = b + size
            ls = sealed; lc = 0; rs = sealed; rc = 0
            while l < r:
                if l & 1:
                    v = T[ls * S + st[l]]
                    lc = lc + cnt[l] - (v & 3); ls = v >> 2
                    l += 1
                if r & 1:
                    r -= 1
                    v = T[st[r] * S + rs]
                    rc = cnt[r] + rc - (v & 3); rs = v >> 2
                l >>= 1; r >>= 1
            v = T[ls * S + rs]
            out.append(lc + rc - (v & 3))
    sys.stdout.write("\n".join(map(str, out)) + ("\n" if out else ""))
main()
